export const VERSION = '1.1.0';

const EMPTY_OPTIONS = Object.freeze(Object.create(null));

/**
 * Create a disposal registry backed by a single FinalizationRegistry.
 *
 * @param {object} [options]
 * @param {string} [options.name='lite-cleanup']
 *   Optional identifier for diagnostics.
 * @param {(tag: any) => void} [options.onCollect]
 *   Called after the FR path fires (target GC'd without explicit unregister).
 *   Not called on explicit unregister.
 * @param {(err: any, tag: any) => void} [options.onError]
 *   Called when a cleanup function throws. If omitted, thrown errors are
 *   swallowed. If onError itself throws, the error is swallowed as a last
 *   resort to avoid corrupting the FR callback.
 * @returns {{
 *   register: (target: object, cleanup: () => void, tag?: any) => object,
 *   unregister: (handle: object | null | undefined) => void,
 *   size: () => number,
 *   name: string
 * }}
 *
 * Held-value contract (LOAD-BEARING):
 *   The `cleanup` closure MUST NOT close over `target`. Capturing the target
 *   keeps it reachable via the FR itself and silently defeats finalization.
 *   Enforced by test/held-value-contract.test.js.
 */
export function createDisposalRegistry(options) {
  const opts = options || EMPTY_OPTIONS;
  const name = opts.name || 'lite-cleanup';
  const onCollect = opts.onCollect;
  const onError = opts.onError;

  if (opts.onCollect !== undefined && typeof opts.onCollect !== 'function') {
    throw new TypeError(name + ': onCollect must be a function');
  }
  if (opts.onError !== undefined && typeof opts.onError !== 'function') {
    throw new TypeError(name + ': onError must be a function');
  }

  let live = 0;

  // Records this registry issued. Weak, so it never pins a handle.
  // Authoritative for ownership AND liveness -- `record.disposed` is
  // advisory only, because the record is handed to the caller.
  const issued = new WeakSet();

  const fr = new FinalizationRegistry(finalize);

  // The record is handed to the caller, so it may be frozen, sealed, or carry
  // a hostile accessor by the time we write to it. `issued` is authoritative
  // for ownership and liveness, which makes these three fields advisory --
  // so a failed write must never propagate. Inside finalize() an escaping
  // TypeError would surface as an uncaught exception in the job queue; inside
  // unregister() it would throw at a caller who did nothing wrong.
  function scrub(record) {
    try {
      record.disposed = true;
      record.cleanup = null;
      record.tag = null;
    } catch (_e) { /* advisory fields only; state already committed */ }
  }

  function finalize(record) {
    if (issued.delete(record) === false) return;
    live--;
    const cleanup = record.cleanup;
    const tag = record.tag;
    scrub(record);
    if (typeof cleanup === 'function') {
      try {
        cleanup();
      } catch (err) {
        if (onError !== undefined) {
          try { onError(err, tag); } catch (_e) { /* swallowed */ }
        }
      }
    }
    if (onCollect !== undefined) {
      try { onCollect(tag); } catch (_e) { /* swallowed */ }
    }
  }

  function register(target, cleanup, tag) {
    // null/undefined means "observe only, nothing to run" -- a documented and
    // used capability (lite-leak's track(target, null, tag) relies on it, and
    // finalize has always guarded the call site). Reject only values that are
    // neither: a string or a number here is a typo, never an intent.
    if (cleanup !== null && cleanup !== undefined && typeof cleanup !== 'function') {
      throw new TypeError(
        name + ': cleanup must be a function, null, or undefined (got ' +
        typeof cleanup + ')'
      );
    }
    if (target === null || (typeof target !== 'object' &&
        typeof target !== 'function' && typeof target !== 'symbol')) {
      throw new TypeError(
        name + ': target must be an object, function or symbol (got ' +
        (target === null ? 'null' : typeof target) + ')'
      );
    }
    // The record IS the FinalizationRegistry held value, and a held value that
    // references its own target keeps that target alive forever -- the
    // finalizer can then never fire. This catches the identity case; a tag that
    // merely *reaches* the target (`{ ref: target }`) cannot be detected without
    // walking the graph, and remains the caller's responsibility under the
    // held-value contract.
    if (tag === target) {
      throw new TypeError(
        name + ': tag must not be the target -- it is stored in the ' +
        'FinalizationRegistry held value and would pin the target forever'
      );
    }
    const record = {
      cleanup: cleanup,
      tag: tag === undefined ? null : tag,
      disposed: false,
    };
    fr.register(target, record, record);  // throws before issued.add / live++
    issued.add(record);
    live++;
    return record;
  }

  function unregister(handle) {
    if (issued.delete(handle) === false) return;
    fr.unregister(handle);
    live--;
    scrub(handle);
  }

  function size() {
    return live;
  }

  return { register: register, unregister: unregister, size: size, name: name };
}
